import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Julia Patacz'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'julia.patacz@nokia.com'


class SwVersion(GenericEMSSIMCommand):
    """Swversion command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Swversion command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SwVersion, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return "sw_version"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_file_detail(line)
                self._parse_state_build_release_date(line)
                self._parse_state_build_release(line)
            except ParsingDone:
                pass
            return super(SwVersion, self).on_new_line(line, is_full_line)

    # 13:12:49          |    fileId        => /bts2//ram/LTE_CurrentBD.xml
    _re_file_detail = re.compile(r"\s+(?P<KEY>\S+)\s*=>\s*(?P<VALUE>\S+)$")

    def _parse_file_detail(self, line):
        if self._regex_helper.search_compiled(SwVersion._re_file_detail, line):
            if 'file_detail' not in self.current_ret.keys():
                self.current_ret['file_detail'] = {}
            self.current_ret['file_detail'][self._regex_helper.group('KEY')] = self._regex_helper.group('VALUE')
            raise ParsingDone

    # 13:12:49          | Active  | TLF18SP_ENB_0000_000012_000000 | TLF18SP_ENB_0000_000012_000000 |      |
    _re_state_build_release = re.compile(
        r"\|\s*(?P<STATE>\S+)\s*\|\s*(?P<BUILD>\S+)\s*\|\s*(?P<RELEASE>\S+)\s+\|.*\|$")

    def _parse_state_build_release(self, line):
        if self._regex_helper.search_compiled(SwVersion._re_state_build_release, line):
            temp_state = self._regex_helper.group('STATE')
            temp_build = self._regex_helper.group('BUILD')
            temp_release = self._regex_helper.group('RELEASE')
            if 'version' not in self.current_ret.keys():
                self.current_ret['version'] = {}
            if temp_state not in self.current_ret['version'].keys():
                self.current_ret['version'][temp_state] = {}
            self.current_ret['version'][temp_state]['build'] = temp_build
            self.current_ret['version'][temp_state]['release'] = temp_release
            self.current_ret['version'][temp_state]['date'] = ''
            raise ParsingDone

    # 13:12:49          | Active  | TLF18SP_ENB_0000_000012_000000 | TLF18SP_ENB_0000_000012_000000 | 26/05/2018 |
    _re_state_build_release_date = re.compile(
        r"\|\s*(?P<STATE>\S+)\s*\|\s*(?P<BUILD>\S+)\s*\|\s*(?P<RELEASE>\S+)\s+\|\s+(?P<DATE>\d+\/\d+\/\d+)\s+\|$")

    def _parse_state_build_release_date(self, line):
        if self._regex_helper.search_compiled(SwVersion._re_state_build_release_date, line):
            temp_state = self._regex_helper.group('STATE')
            temp_build = self._regex_helper.group('BUILD')
            temp_release = self._regex_helper.group('RELEASE')
            temp_date = self._regex_helper.group('DATE')
            if 'version' not in self.current_ret.keys():
                self.current_ret['version'] = {}
            if temp_state not in self.current_ret['version'].keys():
                self.current_ret['version'][temp_state] = {}
            self.current_ret['version'][temp_state]['build'] = temp_build
            self.current_ret['version'][temp_state]['release'] = temp_release
            self.current_ret['version'][temp_state]['date'] = temp_date
            raise ParsingDone


